INSERT OR IGNORE INTO "Property" ("id","title","slug","description","searchText","listingType","status","price","currency","pricePeriod","typeId","cityId","districtId","address","latitude","longitude","rooms","bedrooms","bathrooms","area","landArea","floor","totalFloors","renovation","documentStatus","buildingType","mortgageAvailable","installmentAvailable","isFeatured","isDemo","viewCount","publishedAt","createdAt","updatedAt") VALUES ('demo_prop_menziller_01','Səbail yaşayış massivində rahat 4 otaqlı mənzil','demo-menziller-01','Sakit həyət, işlək infrastruktur və rahat nəqliyyat əlçatanlığı bir arada. Pəncərələr həyətə baxır — küçə səsi minimuma endirilib. Mebel və məişət texnikası qiymətə daxildir. Sənədlər tam qaydasındadır, əməliyyat bir gün ərzində rəsmiləşdirilir. Qeyd: bu, Luxe Home Estate platformasının test rejimi üçün hazırlanmış nümunə elandır. Obyekt, qiymət və əlaqə məlumatları uydurmadır.','sebail yasayis massivinde rahat 4 otaqli menzil sebail neftciler prospekti 6 sakit heyet islek infrastruktur ve rahat neqliyyat elcatanligi bir arada','RENT','PUBLISHED',2400,'AZN','MONTH',(SELECT "id" FROM "PropertyType" WHERE "slug" = 'menziller'),(SELECT "id" FROM "Location" WHERE "slug" = 'baki'),(SELECT "id" FROM "Location" WHERE "slug" = 'baki-sebail'),'Səbail, Neftçilər prospekti 6',40.334483,49.854036,4,3,2,162,NULL,1,17,'DESIGNER','TITLE_DEED','NEW',0,1,1,1,252,'2026-04-20T08:59:00.000Z','2026-04-20T08:59:00.000Z','2026-04-20T08:59:00.000Z');
