INSERT OR IGNORE INTO "Project" ("id","name","slug","description","summary","projectType","status","cityId","address","latitude","longitude","deliveryDate","year","totalArea","floors","unitCount","highlights","timeline","coverUrl","isDemo","isActive","order","createdAt","updatedAt") VALUES ('demo_project_luxe_park_residence','Luxe Park Residence','demo-luxe-park-residence','Dənizkənarı bulvara on dəqiqəlik məsafədə, qapalı həyətli premium yaşayış kompleksi. Layihə 22 mərtəbə və 248 mənzildən ibarətdir; ümumi sahə 34.000 m²-dir. Mənzillərin planlaşdırması müxtəlif ailə ölçülərinə uyğun hazırlanıb, ictimai zonalar isə gündəlik istifadə rahatlığı nəzərə alınaraq layihələndirilib. Qeyd: bu, Luxe Home Estate platformasının test rejimi üçün hazırlanmış nümunə layihə qeydidir. Obyekt, qiymət və əlaqə məlumatları uydurmadır.','Dənizkənarı bulvara on dəqiqəlik məsafədə, qapalı həyətli premium yaşayış kompleksi.','RESIDENTIAL','ONGOING',(SELECT "id" FROM "Location" WHERE "slug" = 'baki'),'Səbail, Luxe Park Residence',40.235587,49.882272,'2027-09-01T09:00:00.000Z',2027,34000,22,248,'["Qapalı həyət və landşaft","Yeraltı parkinq","24/7 mühafizə","Fitnes və SPA zonası"]','[{"step":1,"title":"Layihələndirmə və icazələr","done":true},{"step":2,"title":"Bünövrə və karkas","done":true},{"step":3,"title":"Fasad və daxili işlər","done":false},{"step":4,"title":"İstismara vermə","done":false}]','https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=1600&q=80',1,1,0,'2026-01-13T09:00:00.000Z','2026-01-13T09:00:00.000Z');
